"""Phase 3 — the cross-architecture translator C: weights(A=transformer) -> weights(B=SSM).

Recipe (ported from the NumPy weight_translator that hit ~0.93 zero-shot):
  * sigma rides through EQUIVARIANT vocab maps: B.tok = A.tok @ W_t, etc. So
    whatever substitution donor A encodes is inherited by B for free.
  * the lag k (and the rest of B's interior) is GENERATED by a hypernet from a
    sigma-free positional feature of A:  z = enc(S_pos(A)),  B_interior = th0 + M z.

B is executed differentiably from the emitted weights via torch.func.functional_call,
so C is trained purely on B's task loss -- no pre-distilled targets needed.
"""
import torch
import torch.nn as nn
from torch.func import functional_call

from models import Cfg, LM
from task import make_batch, make_multitask_batch, masked_ce, task_accuracy

VOCAB_KEYS = ("tok.weight", "pos.weight", "head.weight")


def batch_for(task, bs, cfg, g):
    """Single task (dict) or multi-task bundle (list of dicts)."""
    if isinstance(task, list):
        return make_multitask_batch(task, bs, cfg.ctx, cfg.vocab, g)
    return make_batch(task, bs, cfg.ctx, cfg.vocab, g)


# ------------------------- sigma-free positional feature -------------------------
def s_pos_feature(state, cfg):
    """S_pos = P (W_q^T W_k) P^T from donor A's layer-0 attention + pos embedding.

    Carries the lag k (a ridge at column = row - k) and is independent of sigma.
    """
    d = cfg.d_model
    qkv = state["blocks.0.mix.qkv.weight"]            # (3d, d): rows = W_q | W_k | W_v
    Wq, Wk = qkv[:d], qkv[d:2 * d]                    # each (d, d), y = W x
    M_qk = Wq.t() @ Wk                                # (d, d)
    P = state["pos.weight"]                           # (ctx, d)
    S = P @ M_qk @ P.t()                              # (ctx, ctx)
    return S.reshape(-1)                              # (ctx*ctx,)


# ------------------------------- the translator -------------------------------
class Translator(nn.Module):
    def __init__(self, cfg: Cfg, feat_mu, feat_sd, d_z=8, h=64, b_kind="ssm"):
        super().__init__()
        self.cfg = cfg
        d = cfg.d_model
        # reference B: gives the interior init th0 and the exact param spec
        ref = LM(cfg, b_kind)
        self.b_params = dict(ref.named_parameters())
        self.int_keys = [k for k in self.b_params if k not in VOCAB_KEYS]
        th0 = torch.cat([self.b_params[k].detach().reshape(-1) for k in self.int_keys])
        self.register_buffer("th0", th0)
        self.register_buffer("feat_mu", feat_mu)
        self.register_buffer("feat_sd", feat_sd)
        # equivariant vocab maps (sigma rides through these)
        self.W_t = nn.Parameter(torch.eye(d) + 0.01 * torch.randn(d, d))
        self.W_h = nn.Parameter(torch.eye(d) + 0.01 * torch.randn(d, d))
        self.W_p = nn.Parameter(torch.eye(d) + 0.01 * torch.randn(d, d))
        # hypernet: sigma-free feature -> low-dim code -> interior delta
        self.enc = nn.Sequential(nn.Linear(feat_mu.numel(), h), nn.SiLU(),
                                 nn.Linear(h, h), nn.SiLU(), nn.Linear(h, d_z))
        self.M = nn.Parameter(0.01 * torch.randn(th0.numel(), d_z))

    def emit(self, A_state):
        """Produce a full B parameter dict from donor A's weights."""
        feat = (s_pos_feature(A_state, self.cfg) - self.feat_mu) / self.feat_sd
        z = self.enc(feat)
        interior = self.th0 + self.M @ z
        params, off = {}, 0
        for k in self.int_keys:
            n = self.b_params[k].numel()
            params[k] = interior[off:off + n].view_as(self.b_params[k])
            off += n
        params["tok.weight"] = A_state["tok.weight"] @ self.W_t
        params["head.weight"] = A_state["head.weight"] @ self.W_h
        params["pos.weight"] = A_state["pos.weight"] @ self.W_p
        return params


# ------------------------------- featurise zoo -------------------------------
def feat_stats(zoo, cfg):
    F_ = torch.stack([s_pos_feature(z["A"], cfg) for z in zoo])
    return F_.mean(0), F_.std(0) + 1e-6


# --------------------------------- train C ---------------------------------
def run_B(template, params, x):
    return functional_call(template, params, (x,))[0]


def train_translator(cfg, zoo, steps=600, lr=3e-3, bs=64, tasks_per_step=8, seed=0,
                     b_kind="ssm"):
    torch.manual_seed(seed)
    mu, sd = feat_stats(zoo, cfg)
    C = Translator(cfg, mu, sd, b_kind=b_kind)
    template = LM(cfg, b_kind)
    opt = torch.optim.AdamW(C.parameters(), lr=lr)
    g = torch.Generator().manual_seed(424242)
    C.train()
    for step in range(steps):
        idx = torch.randperm(len(zoo), generator=g)[:tasks_per_step]
        opt.zero_grad()
        loss = 0.0
        for i in idx:
            z = zoo[int(i)]
            params = C.emit(z["A"])
            x, y = batch_for(z["task"], bs, cfg, g)
            loss = loss + masked_ce(run_B(template, params, x), y)
        (loss / len(idx)).backward()
        opt.step()
    return C, template


def _acc_of(template, params, cfg, task, iters=8, bs=128, seed=55):
    g = torch.Generator().manual_seed(seed)
    a = 0.0
    with torch.no_grad():
        for _ in range(iters):
            x, y = batch_for(task, bs, cfg, g)
            a += task_accuracy(run_B(template, params, x), y)
    return a / iters


def warm_start_acc(template, init_params, cfg, task, steps=15, lr=3e-3, bs=64):
    """Fine-tune B starting from init_params for a few steps; return task accuracy."""
    return warm_curve(template, init_params, cfg, task, max_steps=steps,
                      every=steps, lr=lr, bs=bs)[steps]


def warm_curve(template, init_params, cfg, task, max_steps=40, every=4, lr=3e-3, bs=64):
    """Fine-tune B from init_params; return {step: accuracy} at 0, every, ..., max_steps."""
    params = {k: v.detach().clone().requires_grad_(True) for k, v in init_params.items()}
    opt = torch.optim.AdamW(list(params.values()), lr=lr)
    g = torch.Generator().manual_seed(321)
    curve = {0: _acc_of(template, params, cfg, task)}
    for step in range(1, max_steps + 1):
        x, y = batch_for(task, bs, cfg, g)
        loss = masked_ce(run_B(template, params, x), y)
        opt.zero_grad()
        loss.backward()
        opt.step()
        if step % every == 0 or step == max_steps:
            curve[step] = _acc_of(template, params, cfg, task)
    return curve


def steps_to_threshold(curve, thr=0.9, cap=None):
    """First fine-tune step whose accuracy >= thr (else `cap`)."""
    for s in sorted(curve):
        if curve[s] >= thr:
            return s
    return cap if cap is not None else max(curve) + 1


def random_B_params(cfg, seed=0, b_kind="ssm"):
    torch.manual_seed(seed)
    return {k: v.detach().clone() for k, v in LM(cfg, b_kind).named_parameters()}


@torch.no_grad()
def eval_translator(C, template, cfg, held, mismatch=False, iters=8, bs=128):
    """Zero-shot task accuracy of B*=C(A*). If mismatch, feed each task the WRONG
    donor's weights (control: should collapse to chance)."""
    C.eval()
    g = torch.Generator().manual_seed(55)
    accs = []
    for j, z in enumerate(held):
        src = held[(j + 1) % len(held)] if mismatch else z
        params = C.emit(src["A"])
        a = 0.0
        for _ in range(iters):
            x, y = batch_for(z["task"], bs, cfg, g)
            a += task_accuracy(run_B(template, params, x), y)
        accs.append(a / iters)
    return sum(accs) / len(accs)
